// URL da página que você deseja carregar
const url = 'https://www.hsfinanceira.com.br/historico_cotacao.php';

// Usando fetch para buscar o conteúdo da outra página
fetch(url)
  .then(response => {
    // Verifica se a resposta da requisição foi bem-sucedida
    if (!response.ok) {
      throw new Error('Erro ao carregar a página');
    }
    // Converte a resposta para texto
    return response.text();
  })
  .then(data => {
    // Inserindo o conteúdo da outra página no elemento com id "conteudo"
    document.getElementById('conteudo').innerHTML = data;
  })
  .catch(error => {
    console.error('Erro:', error);
  });